import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.Dxeykp0S.js";const p=JSON.parse('{"title":"Day 2 · GIL、多线程与多进程","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/02-concurrency.md","filePath":"advanced/02-concurrency.md","lastUpdated":1787141678000}'),l={name:"advanced/02-concurrency.md"};function n(i,t,d,h,c,s){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="day-2-·-gil、多线程与多进程" tabindex="-1">Day 2 · GIL、多线程与多进程 <a class="header-anchor" href="#day-2-·-gil、多线程与多进程" aria-label="Permalink to &quot;Day 2 · GIL、多线程与多进程&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>Python 并发选型绕不开 GIL（全局解释器锁）：传统 CPython 中的多线程通常适合 IO 密集任务，CPU 密集任务通常使用多进程。Python 3.13 开始提供实验性 free-threading（无 GIL）构建，但生态迁移仍需时间。今天把并发选型的判断标准刻进脑子。</p><h2 id="课程目标" tabindex="-1">课程目标 <a class="header-anchor" href="#课程目标" aria-label="Permalink to &quot;课程目标&quot;">​</a></h2><ul><li>理解 GIL 是什么、为什么存在、影响什么</li><li>掌握 <code>concurrent.futures</code> 的 ThreadPoolExecutor 与 ProcessPoolExecutor</li><li>能根据任务类型正确选择：asyncio / 多线程 / 多进程</li><li>了解 Python 3.13 free-threading 的现状</li></ul><h2 id="阅读学习" tabindex="-1">阅读学习 <a class="header-anchor" href="#阅读学习" aria-label="Permalink to &quot;阅读学习&quot;">​</a></h2><ul><li><a href="https://docs.python.org/zh-cn/3/library/concurrent.futures.html" target="_blank" rel="noreferrer">Python 官方：concurrent.futures</a></li><li><a href="https://realpython.com/python-gil/" target="_blank" rel="noreferrer">Real Python: What Is the Python GIL?</a></li><li><a href="https://peps.python.org/pep-0703/" target="_blank" rel="noreferrer">PEP 703：Making the Global Interpreter Lock Optional</a></li><li>选型决策表（背下来）：</li></ul><table tabindex="0"><thead><tr><th>任务类型</th><th>特征</th><th>正确方案</th></tr></thead><tbody><tr><td>IO 密集，高并发连接</td><td>网络请求、DB 查询</td><td>asyncio</td></tr><tr><td>IO 密集，同步库</td><td>调用阻塞型第三方库</td><td>多线程（GIL 在 IO 时释放）</td></tr><tr><td>CPU 密集</td><td>图像处理、加解密、数学计算</td><td>多进程（绕过 GIL）</td></tr><tr><td>CPU 密集 + 未来</td><td>—</td><td>free-threaded Python（观望）</td></tr></tbody></table><h2 id="任务作业" tabindex="-1">任务作业 <a class="header-anchor" href="#任务作业" aria-label="Permalink to &quot;任务作业&quot;">​</a></h2><ol><li><p><strong>GIL 眼见为实</strong>：写一个纯 CPU 计算函数（如计算 π 的蒙特卡洛方法，1 千万次采样），分别用：单线程、4 线程（ThreadPoolExecutor）、4 进程（ProcessPoolExecutor）运行并计时。预期结果：多线程几乎无提升甚至更慢，多进程接近线性加速。记录数据，思考原因。</p></li><li><p><strong>IO 场景反转</strong>：把任务换成&quot;下载 50 个文件&quot;（可用 httpbin.org/delay/1 模拟），分别用单线程、多线程、多进程跑，观察多线程在 IO 场景下的正常加速。结合任务 1 总结规律。</p></li><li><p><strong>进程间通信体验</strong>：用 <code>multiprocessing.Queue</code> 写一个两个进程协作的 demo（一个生产数据，一个消费），观察独立内存空间下的数据传递方式。</p></li><li><p><strong>混合架构</strong>：设计并实现一个图片处理服务的并发架构（模拟即可）：asyncio 接收请求（IO）→ <code>loop.run_in_executor</code> 把图片缩放（CPU）丢进进程池 → 返回结果。画出架构图。</p></li></ol><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><ul><li>GIL 锁住的到底是什么？为什么 IO 操作时线程会释放 GIL？</li><li>为什么多进程能绕过 GIL？代价是什么（内存、序列化、启动开销）？</li><li>多进程间传递数据为什么必须可 pickle？</li><li><code>concurrent.futures</code> 和 <code>asyncio</code> 能混用吗？怎么混？</li><li>NumPy 做矩阵运算时为什么不受 GIL 限制？（提示：C 扩展释放 GIL）</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>记录今天的学习笔记。</p><h2 id="拓展阅读" tabindex="-1">拓展阅读 <a class="header-anchor" href="#拓展阅读" aria-label="Permalink to &quot;拓展阅读&quot;">​</a></h2><ul><li><a href="https://docs.python.org/3/howto/free-threading-python.html" target="_blank" rel="noreferrer">Python 3.13 free-threading 官方指南</a></li><li><a href="https://www.dabeaz.com/GIL/" target="_blank" rel="noreferrer">David Beazley: Understanding the Python GIL（经典演讲）</a></li></ul><h2 id="预告" tabindex="-1">预告 <a class="header-anchor" href="#预告" aria-label="Permalink to &quot;预告&quot;">​</a></h2><p>下一节学习<a href="./03-typing">类型提示</a>——你最熟悉的部分来了，Python 的 TypeScript。</p>',18)])])}const y=e(l,[["render",n]]);export{p as __pageData,y as default};
